BEGIN;
DO $$ DECLARE def TEXT;BEGIN SELECT pg_get_constraintdef(oid) INTO def FROM pg_constraint WHERE conrelid='public."FinanceAccount"'::regclass AND conname='FinanceAccount_controlType_check';ALTER TABLE public."FinanceAccount" DROP CONSTRAINT "FinanceAccount_controlType_check";EXECUTE 'ALTER TABLE public."FinanceAccount" ADD CONSTRAINT "FinanceAccount_controlType_check" CHECK(('||substr(def,8,length(def)-8)||') OR "controlType" IN(''INTEREST_RECEIVABLE'',''INTEREST_PAYABLE''))';SELECT pg_get_constraintdef(oid) INTO def FROM pg_constraint WHERE conrelid='public."FinanceAccount"'::regclass AND conname='FinanceAccount_control_type';ALTER TABLE public."FinanceAccount" DROP CONSTRAINT "FinanceAccount_control_type";EXECUTE 'ALTER TABLE public."FinanceAccount" ADD CONSTRAINT "FinanceAccount_control_type" CHECK(('||substr(def,8,length(def)-8)||') OR(type=''ASSET'' AND "controlType"=''INTEREST_RECEIVABLE'') OR(type=''LIABILITY'' AND "controlType"=''INTEREST_PAYABLE''))';END $$;

CREATE SEQUENCE finance_loan_number AS BIGINT MINVALUE 1 MAXVALUE 9999999999 NO CYCLE;
CREATE TABLE "FinanceLoan"(id UUID PRIMARY KEY,number TEXT NOT NULL UNIQUE,name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 120),"partyId" UUID NOT NULL REFERENCES "FinanceParty" ON DELETE RESTRICT,direction TEXT NOT NULL CHECK(direction IN('RECEIVED','ADVANCED')),"startDate" DATE NOT NULL CHECK("startDate">=DATE '0001-01-01'),"maturityDate" DATE NOT NULL CHECK("maturityDate">="startDate" AND "maturityDate"<=DATE '9999-12-31'),"agreedPrincipal" NUMERIC(20,2) NOT NULL CHECK("agreedPrincipal">0),"annualRate" NUMERIC(10,6) CHECK("annualRate" BETWEEN 0 AND 1000),agreement TEXT NOT NULL CHECK(length(trim(agreement)) BETWEEN 3 AND 1000),"principalAccountId" UUID NOT NULL REFERENCES "FinanceAccount" ON DELETE RESTRICT,"interestAccountId" UUID NOT NULL REFERENCES "FinanceAccount" ON DELETE RESTRICT,"interestResultAccountId" UUID NOT NULL REFERENCES "FinanceAccount" ON DELETE RESTRICT,"manualSchedule" JSONB NOT NULL DEFAULT '[]' CHECK(jsonb_typeof("manualSchedule")='array' AND jsonb_array_length("manualSchedule")<=120),active BOOLEAN NOT NULL DEFAULT true,version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),"usedAt" TIMESTAMPTZ,"createdById" UUID NOT NULL REFERENCES "Person" ON DELETE RESTRICT,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "FinanceLoan_direction_id_idx" ON "FinanceLoan"(direction,id);
CREATE TABLE "FinanceLoanEvent"(id UUID PRIMARY KEY,"movementId" UUID NOT NULL UNIQUE REFERENCES "FinanceMovement" ON DELETE RESTRICT,"loanId" UUID NOT NULL REFERENCES "FinanceLoan" ON DELETE RESTRICT,"journalId" UUID NOT NULL UNIQUE REFERENCES "FinanceJournalEntry" ON DELETE RESTRICT,"effectiveDate" DATE NOT NULL,bucket TEXT NOT NULL CHECK(bucket IN('PRINCIPAL','INTEREST')),amount NUMERIC(20,2) NOT NULL CHECK(amount<>0));
CREATE INDEX "FinanceLoanEvent_loanId_effectiveDate_idx" ON "FinanceLoanEvent"("loanId","effectiveDate");
CREATE TRIGGER "FinanceLoanEvent_immutable" BEFORE UPDATE OR DELETE ON "FinanceLoanEvent" FOR EACH ROW EXECUTE FUNCTION encova_finance_audit_immutable();
CREATE TRIGGER "FinanceLoan_config" BEFORE INSERT OR UPDATE OR DELETE ON "FinanceLoan" FOR EACH STATEMENT EXECUTE FUNCTION encova_finance_config_lock();
ALTER TABLE "FinanceMovement" ADD COLUMN "loanId" UUID REFERENCES "FinanceLoan" ON DELETE RESTRICT;
CREATE FUNCTION encova_finance_loan_balance(target UUID,bucket_name TEXT,cutoff DATE) RETURNS NUMERIC LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT coalesce(sum(amount),0) FROM public."FinanceLoanEvent" WHERE "loanId"=target AND bucket=bucket_name AND "effectiveDate"<=cutoff $$;
CREATE FUNCTION encova_finance_loan_capacity(target UUID,bucket_name TEXT,cutoff DATE) RETURNS NUMERIC LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT coalesce(min(public.encova_finance_loan_balance(target,bucket_name,dates.d)),0) FROM(SELECT cutoff AS d UNION SELECT "effectiveDate" FROM public."FinanceLoanEvent" WHERE "loanId"=target AND bucket=bucket_name AND "effectiveDate">=cutoff)dates $$;
CREATE FUNCTION encova_finance_loan_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE schedule_line JSONB;scheduled NUMERIC:=0;BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'FINANCE_HISTORY_IMMUTABLE' USING ERRCODE='P0001';END IF;
 IF TG_OP='UPDATE' THEN
  IF ROW(NEW.id,NEW.number,NEW."createdById",NEW."createdAt") IS DISTINCT FROM ROW(OLD.id,OLD.number,OLD."createdById",OLD."createdAt") OR(NEW.version<>OLD.version+1 AND(to_jsonb(NEW)-ARRAY['usedAt','updatedAt']) IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['usedAt','updatedAt'])) THEN RAISE EXCEPTION 'FINANCE_STALE_VERSION' USING ERRCODE='P0001';END IF;
  IF OLD."usedAt" IS NOT NULL AND(to_jsonb(NEW)-ARRAY['name','active','version','updatedAt']) IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['name','active','version','updatedAt']) THEN RAISE EXCEPTION 'FINANCE_LOAN_TERMS_USED' USING ERRCODE='P0001';END IF;
  IF NEW."usedAt" IS DISTINCT FROM OLD."usedAt" THEN IF OLD."usedAt" IS NOT NULL OR NOT EXISTS(SELECT 1 FROM public."FinanceLoanEvent" WHERE "loanId"=NEW.id) THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;END IF;
 END IF;
 IF NOT NEW.active AND EXISTS(SELECT 1 FROM public."FinanceLoanEvent" WHERE "loanId"=NEW.id GROUP BY bucket HAVING sum(amount)<>0) THEN RAISE EXCEPTION 'FINANCE_LOAN_OUTSTANDING' USING ERRCODE='P0001';END IF;
 IF TG_OP='INSERT' OR OLD."usedAt" IS NULL THEN
  IF NOT EXISTS(SELECT 1 FROM public."FinanceParty" WHERE id=NEW."partyId" AND active) OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."principalAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"=CASE WHEN NEW.direction='RECEIVED' THEN 'LOAN_PAYABLE' ELSE 'LOAN_RECEIVABLE' END) OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."interestAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"=CASE WHEN NEW.direction='RECEIVED' THEN 'INTEREST_PAYABLE' ELSE 'INTEREST_RECEIVABLE' END) OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."interestResultAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"='NONE' AND type=CASE WHEN NEW.direction='RECEIVED' THEN 'OTHER_EXPENSE' ELSE 'OTHER_INCOME' END) THEN RAISE EXCEPTION 'FINANCE_LOAN_MAPPING' USING ERRCODE='P0001';END IF;
  FOR schedule_line IN SELECT * FROM jsonb_array_elements(NEW."manualSchedule") LOOP
   IF jsonb_typeof(schedule_line) IS DISTINCT FROM 'object' OR schedule_line-ARRAY['dueDate','principal','interest']<>'{}'::jsonb OR schedule_line->>'dueDate' IS NULL OR(schedule_line->>'dueDate')::date NOT BETWEEN NEW."startDate" AND NEW."maturityDate" OR jsonb_typeof(schedule_line->'principal') IS DISTINCT FROM 'string' OR schedule_line->>'principal' !~ '^(0|[1-9][0-9]{0,17})([.][0-9]{1,2})?$' OR jsonb_typeof(schedule_line->'interest') IS DISTINCT FROM 'string' OR schedule_line->>'interest' !~ '^(0|[1-9][0-9]{0,17})([.][0-9]{1,2})?$' THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;scheduled:=scheduled+(schedule_line->>'principal')::numeric;END LOOP;
  IF scheduled>NEW."agreedPrincipal" THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 END IF;RETURN NEW;END $$;
CREATE TRIGGER "FinanceLoan_guard" BEFORE INSERT OR UPDATE OR DELETE ON "FinanceLoan" FOR EACH ROW EXECUTE FUNCTION encova_finance_loan_guard();
CREATE FUNCTION encova_finance_loan_expected(target UUID) RETURNS TABLE("loanId" UUID,bucket TEXT,amount NUMERIC) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT d."loanId",CASE WHEN d.kind IN('LOAN_INTEREST_ACCRUAL','LOAN_INTEREST_SETTLEMENT') THEN 'INTEREST' ELSE 'PRINCIPAL' END,CASE WHEN d.kind IN('LOAN_REPAYMENT','LOAN_INTEREST_SETTLEMENT','LOAN_PRINCIPAL_DECREASE') THEN -d.amount ELSE d.amount END FROM public."FinanceMovement" d WHERE d.id=target AND d.kind IN('LOAN_DISBURSEMENT','LOAN_REPAYMENT','LOAN_INTEREST_ACCRUAL','LOAN_INTEREST_SETTLEMENT','LOAN_PRINCIPAL_INCREASE','LOAN_PRINCIPAL_DECREASE')
 UNION ALL SELECT v."loanId",v.bucket,-v.amount FROM public."FinanceMovement" d JOIN public."FinanceLoanEvent" v ON v."movementId"=d."reversalOfId" WHERE d.id=target AND d.kind='REVERSAL';
$$;
ALTER FUNCTION encova_finance_movement_lines(UUID) RENAME TO encova_finance_movement_lines_f21;
CREATE FUNCTION encova_finance_movement_lines(target UUID) RETURNS TABLE(sequence INTEGER,"accountId" UUID,description TEXT,debit NUMERIC,credit NUMERIC,"projectId" UUID,"partyId" UUID) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT * FROM public.encova_finance_movement_lines_f21(target)
 UNION ALL SELECT legs.sequence,legs.account,d.description,CASE WHEN legs.sequence=1 THEN d.amount ELSE 0::numeric END,CASE WHEN legs.sequence=2 THEN d.amount ELSE 0::numeric END,d."projectId",l."partyId" FROM public."FinanceMovement" d JOIN public."FinanceLoan" l ON l.id=d."loanId" LEFT JOIN public."FinanceCashAccount" cash ON cash.id=coalesce(d."fromCashId",d."toCashId") CROSS JOIN LATERAL(VALUES
 (1,CASE WHEN d.kind='LOAN_DISBURSEMENT' THEN CASE WHEN l.direction='RECEIVED' THEN cash."glAccountId" ELSE l."principalAccountId" END WHEN d.kind='LOAN_REPAYMENT' THEN CASE WHEN l.direction='RECEIVED' THEN l."principalAccountId" ELSE cash."glAccountId" END WHEN d.kind='LOAN_INTEREST_ACCRUAL' THEN CASE WHEN l.direction='RECEIVED' THEN l."interestResultAccountId" ELSE l."interestAccountId" END WHEN d.kind='LOAN_INTEREST_SETTLEMENT' THEN CASE WHEN l.direction='RECEIVED' THEN l."interestAccountId" ELSE cash."glAccountId" END WHEN d.kind='LOAN_PRINCIPAL_INCREASE' THEN CASE WHEN l.direction='RECEIVED' THEN d."counterAccountId" ELSE l."principalAccountId" END ELSE CASE WHEN l.direction='RECEIVED' THEN l."principalAccountId" ELSE d."counterAccountId" END END),
 (2,CASE WHEN d.kind='LOAN_DISBURSEMENT' THEN CASE WHEN l.direction='RECEIVED' THEN l."principalAccountId" ELSE cash."glAccountId" END WHEN d.kind='LOAN_REPAYMENT' THEN CASE WHEN l.direction='RECEIVED' THEN cash."glAccountId" ELSE l."principalAccountId" END WHEN d.kind='LOAN_INTEREST_ACCRUAL' THEN CASE WHEN l.direction='RECEIVED' THEN l."interestAccountId" ELSE l."interestResultAccountId" END WHEN d.kind='LOAN_INTEREST_SETTLEMENT' THEN CASE WHEN l.direction='RECEIVED' THEN cash."glAccountId" ELSE l."interestAccountId" END WHEN d.kind='LOAN_PRINCIPAL_INCREASE' THEN CASE WHEN l.direction='RECEIVED' THEN l."principalAccountId" ELSE d."counterAccountId" END ELSE CASE WHEN l.direction='RECEIVED' THEN d."counterAccountId" ELSE l."principalAccountId" END END))legs(sequence,account) WHERE d.id=target AND d.kind IN('LOAN_DISBURSEMENT','LOAN_REPAYMENT','LOAN_INTEREST_ACCRUAL','LOAN_INTEREST_SETTLEMENT','LOAN_PRINCIPAL_INCREASE','LOAN_PRINCIPAL_DECREASE');
$$;
ALTER FUNCTION encova_finance_movement_validate(UUID) RENAME TO encova_finance_movement_validate_f21;
CREATE FUNCTION encova_finance_movement_validate(target UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE d public."FinanceMovement"%ROWTYPE;l public."FinanceLoan"%ROWTYPE;v RECORD;cash_in BOOLEAN;cash_out BOOLEAN;BEGIN
 SELECT * INTO d FROM public."FinanceMovement" WHERE id=target FOR UPDATE;
 IF d.kind NOT LIKE 'LOAN_%' THEN PERFORM public.encova_finance_movement_validate_f21(target);ELSE
  SELECT * INTO l FROM public."FinanceLoan" WHERE id=d."loanId" FOR UPDATE;
  IF d.state<>'DRAFT' OR l.id IS NULL OR NOT l.active OR d."postingDate"<l."startDate" OR d."partyId" IS DISTINCT FROM l."partyId" OR d."controlAccountId" IS NOT NULL OR d."billId" IS NOT NULL OR d."projectId" IS NOT NULL OR NOT EXISTS(SELECT 1 FROM public."FinanceParty" WHERE id=l."partyId" AND active) THEN RAISE EXCEPTION 'FINANCE_LOAN_MAPPING' USING ERRCODE='P0001';END IF;
  IF NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=l."principalAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"=CASE WHEN l.direction='RECEIVED' THEN 'LOAN_PAYABLE' ELSE 'LOAN_RECEIVABLE' END) OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=l."interestAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"=CASE WHEN l.direction='RECEIVED' THEN 'INTEREST_PAYABLE' ELSE 'INTEREST_RECEIVABLE' END) OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=l."interestResultAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"='NONE' AND type=CASE WHEN l.direction='RECEIVED' THEN 'OTHER_EXPENSE' ELSE 'OTHER_INCOME' END) THEN RAISE EXCEPTION 'FINANCE_LOAN_MAPPING' USING ERRCODE='P0001';END IF;
  cash_in:=(l.direction='RECEIVED' AND d.kind='LOAN_DISBURSEMENT') OR(l.direction='ADVANCED' AND d.kind IN('LOAN_REPAYMENT','LOAN_INTEREST_SETTLEMENT'));
  cash_out:=(l.direction='ADVANCED' AND d.kind='LOAN_DISBURSEMENT') OR(l.direction='RECEIVED' AND d.kind IN('LOAN_REPAYMENT','LOAN_INTEREST_SETTLEMENT'));
  IF(d."toCashId" IS NOT NULL)<>cash_in OR(d."fromCashId" IS NOT NULL)<>cash_out OR(d."counterAccountId" IS NOT NULL)<>(d.kind IN('LOAN_PRINCIPAL_INCREASE','LOAN_PRINCIPAL_DECREASE')) THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  IF(cash_in OR cash_out) AND NOT EXISTS(SELECT 1 FROM public."FinanceCashAccount" c JOIN public."FinanceAccount" a ON a.id=c."glAccountId" WHERE c.id=coalesce(d."fromCashId",d."toCashId") AND c.active AND a.active AND a."controlType"='CASH' AND a."isPosting" AND a.currency='PKR') THEN RAISE EXCEPTION 'FINANCE_LOAN_MAPPING' USING ERRCODE='P0001';END IF;
  IF d.kind IN('LOAN_PRINCIPAL_INCREASE','LOAN_PRINCIPAL_DECREASE') AND(d."approvalEvidence" IS NULL OR length(trim(d."approvalEvidence"))<3 OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=d."counterAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"='NONE' AND currency='PKR')) THEN RAISE EXCEPTION 'FINANCE_APPROVAL_REQUIRED' USING ERRCODE='P0001';END IF;
 END IF;
 FOR v IN SELECT * FROM public.encova_finance_loan_expected(target) LOOP
  IF v.amount<0 AND public.encova_finance_loan_capacity(v."loanId",v.bucket,d."postingDate") < -v.amount THEN RAISE EXCEPTION 'FINANCE_LOAN_CAPACITY' USING ERRCODE='P0001';END IF;
  IF v.bucket='PRINCIPAL' AND v.amount>0 AND EXISTS(SELECT 1 FROM(SELECT d."postingDate" AS dt UNION SELECT "effectiveDate" FROM public."FinanceLoanEvent" WHERE "loanId"=v."loanId" AND "effectiveDate">=d."postingDate")dates JOIN public."FinanceLoan" loan ON loan.id=v."loanId" WHERE public.encova_finance_loan_balance(v."loanId",'PRINCIPAL',dates.dt)+v.amount>loan."agreedPrincipal") THEN RAISE EXCEPTION 'FINANCE_LOAN_LIMIT' USING ERRCODE='P0001';END IF;
 END LOOP;
END $$;
ALTER FUNCTION encova_finance_movement_effects(UUID,UUID,UUID) RENAME TO encova_finance_movement_effects_f21;
CREATE FUNCTION encova_finance_movement_effects(actor UUID,target UUID,entry_id UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN
 INSERT INTO public."FinanceLoanEvent"(id,"movementId","loanId","journalId","effectiveDate",bucket,amount) SELECT gen_random_uuid(),target,v."loanId",entry_id,d."postingDate",v.bucket,v.amount FROM public.encova_finance_loan_expected(target)v JOIN public."FinanceMovement" d ON d.id=target;
 UPDATE public."FinanceLoan" SET "usedAt"=coalesce("usedAt",CURRENT_TIMESTAMP) WHERE id IN(SELECT "loanId" FROM public.encova_finance_loan_expected(target));
 UPDATE public."FinanceParty" SET "usedAt"=coalesce("usedAt",CURRENT_TIMESTAMP) WHERE id IN(SELECT l."partyId" FROM public."FinanceLoan" l JOIN public.encova_finance_loan_expected(target)x ON x."loanId"=l.id);
 PERFORM public.encova_finance_movement_effects_f21(actor,target,entry_id);
END $$;
ALTER FUNCTION encova_finance_check_movement(UUID) RENAME TO encova_finance_check_movement_f21;
CREATE FUNCTION encova_finance_check_movement(target UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE d public."FinanceMovement"%ROWTYPE;j UUID;BEGIN
 IF target IS NULL THEN RETURN;END IF;PERFORM public.encova_finance_check_movement_f21(target);SELECT * INTO d FROM public."FinanceMovement" WHERE id=target;SELECT id INTO j FROM public."FinanceJournalEntry" WHERE "movementId"=target;
 IF d.state<>'POSTED' THEN IF EXISTS(SELECT 1 FROM public."FinanceLoanEvent" WHERE "movementId"=target) THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;RETURN;END IF;
 IF EXISTS((SELECT "loanId",bucket,amount FROM public."FinanceLoanEvent" WHERE "movementId"=target) EXCEPT(SELECT * FROM public.encova_finance_loan_expected(target))) OR EXISTS((SELECT * FROM public.encova_finance_loan_expected(target)) EXCEPT(SELECT "loanId",bucket,amount FROM public."FinanceLoanEvent" WHERE "movementId"=target)) OR EXISTS(SELECT 1 FROM public."FinanceLoanEvent" WHERE "movementId"=target AND("journalId"<>j OR "effectiveDate"<>d."postingDate")) THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;
 IF EXISTS(SELECT 1 FROM(SELECT e.bucket,l."agreedPrincipal",sum(e.amount) OVER(PARTITION BY e."loanId",e.bucket ORDER BY e."effectiveDate" RANGE UNBOUNDED PRECEDING) balance FROM public."FinanceLoanEvent" e JOIN public."FinanceLoan" l ON l.id=e."loanId" WHERE e."loanId" IN(SELECT "loanId" FROM public.encova_finance_loan_expected(target)))v WHERE balance<0 OR(bucket='PRINCIPAL' AND balance>"agreedPrincipal")) THEN RAISE EXCEPTION 'FINANCE_LOAN_CAPACITY' USING ERRCODE='P0001';END IF;
END $$;
CREATE FUNCTION encova_finance_loan_event_check() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN PERFORM public.encova_finance_check_movement(NEW."movementId");RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER "FinanceLoanEvent_valid" AFTER INSERT ON "FinanceLoanEvent" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION encova_finance_loan_event_check();
DO $$ DECLARE def TEXT;BEGIN SELECT pg_get_constraintdef(oid) INTO def FROM pg_constraint WHERE conrelid='public."FinanceMovement"'::regclass AND conname='FinanceMovement_kind_check';ALTER TABLE public."FinanceMovement" DROP CONSTRAINT "FinanceMovement_kind_check";EXECUTE 'ALTER TABLE public."FinanceMovement" ADD CONSTRAINT "FinanceMovement_kind_check" CHECK(('||substr(def,8,length(def)-8)||') OR kind IN(''LOAN_DISBURSEMENT'',''LOAN_REPAYMENT'',''LOAN_INTEREST_ACCRUAL'',''LOAN_INTEREST_SETTLEMENT'',''LOAN_PRINCIPAL_INCREASE'',''LOAN_PRINCIPAL_DECREASE''))';SELECT pg_get_constraintdef(oid) INTO def FROM pg_constraint WHERE conrelid='public."FinanceMovement"'::regclass AND conname='FinanceMovement_source_shape';ALTER TABLE public."FinanceMovement" DROP CONSTRAINT "FinanceMovement_source_shape";EXECUTE 'ALTER TABLE public."FinanceMovement" ADD CONSTRAINT "FinanceMovement_source_shape" CHECK(('||substr(def,8,length(def)-8)||' AND(kind=''REVERSAL'' OR "loanId" IS NULL)) OR(kind IN(''LOAN_DISBURSEMENT'',''LOAN_REPAYMENT'',''LOAN_INTEREST_ACCRUAL'',''LOAN_INTEREST_SETTLEMENT'',''LOAN_PRINCIPAL_INCREASE'',''LOAN_PRINCIPAL_DECREASE'') AND "loanId" IS NOT NULL AND "partyId" IS NOT NULL AND "controlAccountId" IS NULL AND "billId" IS NULL AND "projectId" IS NULL AND "reversalOfId" IS NULL))';END $$;
CREATE OR REPLACE FUNCTION encova_finance_movement_command(actor UUID,provider TEXT,session_id TEXT,verified_at TIMESTAMPTZ,action TEXT,input JSONB,request_key TEXT,request_id UUID) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE d public."FinanceMovement"%ROWTYPE;o public."FinanceMovement"%ROWTYPE;r public."FinanceLedgerReceipt"%ROWTYPE;reason TEXT;digest TEXT;operation_name TEXT;result JSONB;entry_id UUID;original_id UUID;original_version INTEGER;original_number TEXT;BEGIN
 IF action IS NULL OR action NOT IN('CREATE','UPDATE','POST','VOID','REVERSE') OR jsonb_typeof(input) IS DISTINCT FROM 'object' OR request_key IS NULL OR length(request_key) NOT BETWEEN 8 AND 128 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 IF verified_at IS NULL OR verified_at<CURRENT_TIMESTAMP-interval '5 minutes' OR verified_at>CURRENT_TIMESTAMP+interval '5 seconds' THEN RAISE EXCEPTION 'FINANCE_REAUTH_REQUIRED' USING ERRCODE='P0001';END IF;
 reason:=trim(input->>'reason');IF reason IS NULL OR length(reason) NOT BETWEEN 3 AND 500 OR input-(CASE WHEN action='CREATE' THEN ARRAY['kind','reference','documentDate','postingDate','description','evidence','approvalEvidence','currency','amount','fromCashId','toCashId','partyId','controlAccountId','counterAccountId','projectId','billId','loanId','reason'] WHEN action='UPDATE' THEN ARRAY['id','expectedVersion','kind','reference','documentDate','postingDate','description','evidence','approvalEvidence','currency','amount','fromCashId','toCashId','partyId','controlAccountId','counterAccountId','projectId','billId','loanId','reason'] WHEN action='REVERSE' THEN ARRAY['id','expectedVersion','postingDate','reason'] ELSE ARRAY['id','expectedVersion','reason'] END)<>'{}'::jsonb THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 PERFORM pg_advisory_xact_lock(987661);PERFORM public.encova_finance_lock_person(actor);
 IF NOT EXISTS(SELECT 1 FROM public."Person" WHERE id=actor AND role='SUPER_ADMIN' AND status='ACTIVE') OR NOT public.encova_finance_session_ok(actor,provider,session_id) OR NOT EXISTS(SELECT 1 FROM public."FinanceGrant" WHERE "userId"=actor AND "revokedAt" IS NULL) THEN RAISE EXCEPTION 'FINANCE_FORBIDDEN' USING ERRCODE='P0001';END IF;
 operation_name:='MOVEMENT_'||action;digest:=encode(sha256(convert_to(jsonb_strip_nulls(input)::text,'UTF8')),'hex');SELECT * INTO r FROM public."FinanceLedgerReceipt" WHERE "actorId"=actor AND operation=operation_name AND key=request_key;
 IF FOUND THEN IF r."requestHash"<>digest THEN RAISE EXCEPTION 'FINANCE_IDEMPOTENCY_CONFLICT' USING ERRCODE='P0001';END IF;RETURN r.result;END IF;
 PERFORM pg_advisory_xact_lock(629815);
 IF action<>'CREATE' THEN
  IF jsonb_typeof(input->'expectedVersion') IS DISTINCT FROM 'number' OR(input->>'expectedVersion')::integer<1 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  SELECT * INTO d FROM public."FinanceMovement" WHERE id=(input->>'id')::uuid FOR UPDATE;
  IF d.id IS NULL THEN RAISE EXCEPTION 'FINANCE_NOT_FOUND' USING ERRCODE='P0001';END IF;
  IF d.version<>(input->>'expectedVersion')::integer THEN RAISE EXCEPTION 'FINANCE_STALE_VERSION' USING ERRCODE='P0001';END IF;
  IF(action='REVERSE' AND d.state<>'POSTED') OR(action<>'REVERSE' AND d.state<>'DRAFT') THEN RAISE EXCEPTION 'FINANCE_MOVEMENT_IMMUTABLE' USING ERRCODE='P0001';END IF;
 END IF;
 IF action IN('CREATE','UPDATE') THEN
  IF input->>'kind' IS NULL OR input->>'kind' NOT IN('TRANSFER','CAPITAL_CONTRIBUTION','CAPITAL_RETURN','DISTRIBUTION','NONCASH_CAPITAL','FOUNDER_OUTLAY','FOUNDER_BILL_SETTLEMENT','FOUNDER_REIMBURSEMENT','LOAN_DISBURSEMENT','LOAN_REPAYMENT','LOAN_INTEREST_ACCRUAL','LOAN_INTEREST_SETTLEMENT','LOAN_PRINCIPAL_INCREASE','LOAN_PRINCIPAL_DECREASE') OR input->>'currency' IS DISTINCT FROM 'PKR' OR jsonb_typeof(input->'amount') IS DISTINCT FROM 'string' OR input->>'amount' !~ '^(0|[1-9][0-9]{0,17})([.][0-9]{1,2})?$' OR(input->>'amount')::numeric<=0 OR input->>'documentDate' IS NULL OR input->>'documentDate' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR input->>'postingDate' IS NULL OR input->>'postingDate' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  IF input->>'kind' LIKE 'LOAN_%' THEN input:=input||jsonb_build_object('partyId',(SELECT "partyId" FROM public."FinanceLoan" WHERE id=(input->>'loanId')::uuid));END IF;
  IF input->>'kind'='TRANSFER'  AND(input->>'partyId' IS NOT NULL OR input->>'controlAccountId' IS NOT NULL OR input->>'counterAccountId' IS NOT NULL OR input->>'projectId' IS NOT NULL OR input->>'approvalEvidence' IS NOT NULL OR input->>'billId' IS NOT NULL) THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  IF action='CREATE' THEN INSERT INTO public."FinanceMovement"(id,number,kind,reference,"documentDate","postingDate",description,evidence,"approvalEvidence",currency,amount,"fromCashId","toCashId","partyId","controlAccountId","counterAccountId","projectId","billId","loanId","createdById") VALUES(gen_random_uuid(),'MVT-'||lpad(nextval('public.finance_movement_number')::text,10,'0'),input->>'kind',input->>'reference',(input->>'documentDate')::date,(input->>'postingDate')::date,input->>'description',input->>'evidence',input->>'approvalEvidence','PKR',(input->>'amount')::numeric,(input->>'fromCashId')::uuid,(input->>'toCashId')::uuid,(input->>'partyId')::uuid,(input->>'controlAccountId')::uuid,(input->>'counterAccountId')::uuid,(input->>'projectId')::uuid,(input->>'billId')::uuid,(input->>'loanId')::uuid,actor) RETURNING * INTO d;
  ELSE IF input->>'kind' IS DISTINCT FROM d.kind THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;UPDATE public."FinanceMovement" SET "loanId"=(input->>'loanId')::uuid,"partyId"=(input->>'partyId')::uuid,"controlAccountId"=(input->>'controlAccountId')::uuid,"counterAccountId"=(input->>'counterAccountId')::uuid,"projectId"=(input->>'projectId')::uuid,"billId"=(input->>'billId')::uuid,"approvalEvidence"=input->>'approvalEvidence',reference=input->>'reference',"documentDate"=(input->>'documentDate')::date,"postingDate"=(input->>'postingDate')::date,description=input->>'description',evidence=input->>'evidence',amount=(input->>'amount')::numeric,"fromCashId"=(input->>'fromCashId')::uuid,"toCashId"=(input->>'toCashId')::uuid,"updatedAt"=CURRENT_TIMESTAMP,version=version+1 WHERE id=d.id RETURNING * INTO d;END IF;
 ELSIF action='VOID' THEN UPDATE public."FinanceMovement" SET state='VOIDED',version=version+1,"updatedAt"=CURRENT_TIMESTAMP WHERE id=d.id RETURNING * INTO d;
 ELSIF action='REVERSE' THEN
  IF d.kind='REVERSAL' OR input->>'postingDate' IS NULL OR input->>'postingDate' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR EXISTS(SELECT 1 FROM public."FinanceMovement" WHERE "reversalOfId"=d.id) THEN RAISE EXCEPTION 'FINANCE_REVERSAL_INVALID' USING ERRCODE='P0001';END IF;
  o:=d;original_id:=d.id;original_number:=d.number;original_version:=d.version;
  INSERT INTO public."FinanceMovement" SELECT x.* FROM jsonb_populate_record(NULL::public."FinanceMovement",to_jsonb(o)||jsonb_build_object('id',gen_random_uuid(),'number','MVT-'||lpad(nextval('public.finance_movement_number')::text,10,'0'),'kind','REVERSAL','reversalOfId',o.id,'documentDate',(input->>'postingDate')::date,'postingDate',(input->>'postingDate')::date,'state','DRAFT','version',1,'sourceSnapshot',NULL,'createdById',actor,'createdAt',CURRENT_TIMESTAMP,'updatedAt',CURRENT_TIMESTAMP,'evidence',reason)) x RETURNING * INTO d;
  entry_id:=public.encova_finance_emit_journal(actor,'MOVEMENT',d.id,d."postingDate",reason);SELECT * INTO d FROM public."FinanceMovement" WHERE id=d.id;
 ELSE entry_id:=public.encova_finance_emit_journal(actor,'MOVEMENT',d.id,d."postingDate",reason);SELECT * INTO d FROM public."FinanceMovement" WHERE id=d.id;END IF;
 result:=CASE WHEN action='REVERSE' THEN jsonb_build_object('id',original_id,'version',original_version,'number',original_number,'journalId',entry_id,'reversalId',d.id) ELSE jsonb_build_object('id',d.id,'version',d.version,'number',d.number,'journalId',entry_id) END;
 INSERT INTO public."FinanceLedgerReceipt"(id,"actorId",operation,key,"requestHash",result) VALUES(gen_random_uuid(),actor,operation_name,request_key,digest,result);
 INSERT INTO public."FinanceAuditEvent"(id,"actorId",action,"entityType","entityId",reason,data,"requestId") VALUES(gen_random_uuid(),actor,'FINANCE_'||operation_name,'FinanceMovement',coalesce(original_id,d.id),reason,jsonb_build_object('journalId',entry_id,'snapshot',to_jsonb(d)||jsonb_build_object('amount',d.amount::text)),request_id);RETURN result;
EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'FINANCE_DUPLICATE' USING ERRCODE='P0001';
 WHEN check_violation OR not_null_violation OR foreign_key_violation OR invalid_datetime_format OR datetime_field_overflow OR invalid_text_representation OR numeric_value_out_of_range THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';
END $$;
ALTER FUNCTION encova_finance_movement_snapshot(UUID) RENAME TO encova_finance_movement_snapshot_f21;
CREATE FUNCTION encova_finance_movement_snapshot(target UUID) RETURNS JSONB LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT public.encova_finance_movement_snapshot_f21(target)||CASE WHEN d.kind LIKE 'LOAN_%' THEN jsonb_build_object('loan',to_jsonb(l)||jsonb_build_object('agreedPrincipal',l."agreedPrincipal"::text,'annualRate',l."annualRate"::text)) ELSE '{}'::jsonb END FROM public."FinanceMovement" d LEFT JOIN public."FinanceLoan" l ON l.id=d."loanId" WHERE d.id=target $$;
CREATE FUNCTION encova_finance_loan_command(actor UUID,provider TEXT,session_id TEXT,verified_at TIMESTAMPTZ,action TEXT,input JSONB,request_key TEXT,request_id UUID) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE item public."FinanceLoan"%ROWTYPE;prior public."FinanceLedgerReceipt"%ROWTYPE;reason TEXT;digest TEXT;result JSONB;BEGIN
 IF action IS NULL OR action NOT IN('CREATE','UPDATE','ARCHIVE','REACTIVATE') OR jsonb_typeof(input) IS DISTINCT FROM 'object' OR request_key IS NULL OR length(request_key) NOT BETWEEN 8 AND 128 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 IF verified_at IS NULL OR verified_at<CURRENT_TIMESTAMP-interval '5 minutes' OR verified_at>CURRENT_TIMESTAMP+interval '5 seconds' THEN RAISE EXCEPTION 'FINANCE_REAUTH_REQUIRED' USING ERRCODE='P0001';END IF;
 reason:=trim(input->>'reason');IF reason IS NULL OR length(reason) NOT BETWEEN 3 AND 500 OR input-(CASE WHEN action='CREATE' THEN ARRAY['name','partyId','direction','startDate','maturityDate','agreedPrincipal','annualRate','agreement','principalAccountId','interestAccountId','interestResultAccountId','manualSchedule','reason'] WHEN action='UPDATE' THEN ARRAY['id','expectedVersion','name','partyId','direction','startDate','maturityDate','agreedPrincipal','annualRate','agreement','principalAccountId','interestAccountId','interestResultAccountId','manualSchedule','reason'] ELSE ARRAY['id','expectedVersion','reason'] END)<>'{}'::jsonb THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 PERFORM pg_advisory_xact_lock(987661);PERFORM public.encova_finance_lock_person(actor);
 IF NOT EXISTS(SELECT 1 FROM public."Person" WHERE id=actor AND role='SUPER_ADMIN' AND status='ACTIVE') OR NOT public.encova_finance_session_ok(actor,provider,session_id) OR NOT EXISTS(SELECT 1 FROM public."FinanceGrant" WHERE "userId"=actor AND "revokedAt" IS NULL) THEN RAISE EXCEPTION 'FINANCE_FORBIDDEN' USING ERRCODE='P0001';END IF;
 digest:=encode(sha256(convert_to(jsonb_strip_nulls(input)::text,'UTF8')),'hex');SELECT * INTO prior FROM public."FinanceLedgerReceipt" WHERE "actorId"=actor AND operation='LOAN_'||action AND key=request_key;
 IF FOUND THEN IF prior."requestHash"<>digest THEN RAISE EXCEPTION 'FINANCE_IDEMPOTENCY_CONFLICT' USING ERRCODE='P0001';END IF;RETURN prior.result;END IF;
 PERFORM pg_advisory_xact_lock(629815);
 IF action<>'CREATE' THEN
  IF jsonb_typeof(input->'expectedVersion') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  SELECT * INTO item FROM public."FinanceLoan" WHERE id=(input->>'id')::uuid FOR UPDATE;
  IF item.id IS NULL THEN RAISE EXCEPTION 'FINANCE_NOT_FOUND' USING ERRCODE='P0001';END IF;
  IF item.version<>(input->>'expectedVersion')::integer THEN RAISE EXCEPTION 'FINANCE_STALE_VERSION' USING ERRCODE='P0001';END IF;
 END IF;
 IF action IN('CREATE','UPDATE') THEN
  IF jsonb_typeof(input->'agreedPrincipal') IS DISTINCT FROM 'string' OR input->>'agreedPrincipal' !~ '^[1-9][0-9]{0,17}([.][0-9]{1,2})?$|^0[.][0-9]{1,2}$' OR(input->>'agreedPrincipal')::numeric<=0 OR(input->>'annualRate' IS NOT NULL AND(jsonb_typeof(input->'annualRate')<>'string' OR input->>'annualRate' !~ '^(0|[1-9][0-9]{0,3})([.][0-9]{1,6})?$')) OR jsonb_typeof(input->'manualSchedule') IS DISTINCT FROM 'array' OR input->>'startDate' IS NULL OR input->>'startDate' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR input->>'maturityDate' IS NULL OR input->>'maturityDate' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  IF action='CREATE' THEN
   INSERT INTO public."FinanceLoan" SELECT x.* FROM jsonb_populate_record(NULL::public."FinanceLoan",input||jsonb_build_object('id',gen_random_uuid(),'number','LOAN-'||lpad(nextval('public.finance_loan_number')::text,10,'0'),'active',true,'version',1,'usedAt',NULL,'createdById',actor,'createdAt',CURRENT_TIMESTAMP,'updatedAt',CURRENT_TIMESTAMP))x RETURNING * INTO item;
  ELSE
   UPDATE public."FinanceLoan" SET name=input->>'name',"partyId"=(input->>'partyId')::uuid,direction=input->>'direction',"startDate"=(input->>'startDate')::date,"maturityDate"=(input->>'maturityDate')::date,"agreedPrincipal"=(input->>'agreedPrincipal')::numeric,"annualRate"=(input->>'annualRate')::numeric,agreement=input->>'agreement',"principalAccountId"=(input->>'principalAccountId')::uuid,"interestAccountId"=(input->>'interestAccountId')::uuid,"interestResultAccountId"=(input->>'interestResultAccountId')::uuid,"manualSchedule"=input->'manualSchedule',version=version+1,"updatedAt"=CURRENT_TIMESTAMP WHERE id=item.id RETURNING * INTO item;
  END IF;
 ELSE UPDATE public."FinanceLoan" SET active=(action='REACTIVATE'),version=version+1,"updatedAt"=CURRENT_TIMESTAMP WHERE id=item.id RETURNING * INTO item;END IF;
 result:=jsonb_build_object('id',item.id,'number',item.number,'version',item.version);
 INSERT INTO public."FinanceLedgerReceipt"(id,"actorId",operation,key,"requestHash",result) VALUES(gen_random_uuid(),actor,'LOAN_'||action,request_key,digest,result);
 INSERT INTO public."FinanceAuditEvent"(id,"actorId",action,"entityType","entityId",reason,data,"requestId") VALUES(gen_random_uuid(),actor,'FINANCE_LOAN_'||action,'FinanceLoan',item.id,reason,jsonb_build_object('snapshot',to_jsonb(item)||jsonb_build_object('agreedPrincipal',item."agreedPrincipal"::text,'annualRate',item."annualRate"::text)),request_id);RETURN result;
 EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'FINANCE_DUPLICATE' USING ERRCODE='P0001';WHEN check_violation OR not_null_violation OR foreign_key_violation OR invalid_datetime_format OR datetime_field_overflow OR invalid_text_representation OR numeric_value_out_of_range THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';
END $$;

DO $$ DECLARE item RECORD;role_name TEXT;t TEXT;BEGIN
 FOREACH t IN ARRAY ARRAY['FinanceLoan','FinanceLoanEvent'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC',t);IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='encova_app') THEN EXECUTE format('GRANT SELECT ON public.%I TO encova_app',t);EXECUTE format('CREATE POLICY encova_server_read ON public.%I FOR SELECT TO encova_app USING(true)',t);END IF;END LOOP;
 FOR item IN SELECT oid::regprocedure AS signature FROM pg_proc WHERE pronamespace='public'::regnamespace AND(proname LIKE 'encova_finance_loan_%' OR proname LIKE 'encova_finance_movement_%' OR proname LIKE 'encova_finance_check_movement%') LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',item.signature);FOREACH role_name IN ARRAY ARRAY['anon','authenticated','encova_app'] LOOP IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=role_name) THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',item.signature,role_name);END IF;END LOOP;END LOOP;
 REVOKE ALL ON SEQUENCE public.finance_loan_number FROM PUBLIC;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='encova_app') THEN GRANT EXECUTE ON FUNCTION encova_finance_loan_command(UUID,TEXT,TEXT,TIMESTAMPTZ,TEXT,JSONB,TEXT,UUID),encova_finance_movement_command(UUID,TEXT,TEXT,TIMESTAMPTZ,TEXT,JSONB,TEXT,UUID) TO encova_app;END IF;
END $$;
COMMIT;
